.chat-wrap { display: flex; flex-direction: column; gap: 15px; width: 280px; font-family: sans-serif; }
.chat-bubble {
  padding: 12px 20px; border-radius: 20px; color: #fff; font-size: 14px;
  opacity: 0; transform: translateY(20px);
  animation: popIn 0.5s forwards cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.chat-left { background: #333; align-self: flex-start; border-bottom-left-radius: 5px; }
.chat-right { 
  background: linear-gradient(135deg, #6c63ff, #ff007f); align-self: flex-end; 
  border-bottom-right-radius: 5px; box-shadow: 0 5px 15px rgba(108,99,255,0.4); 
}
@keyframes popIn { to { opacity: 1; transform: translateY(0); } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';
const wrap = document.createElement('div');
wrap.className = 'chat-wrap';

const messages = [
  { text: "Hey! How is the new update?", type: "chat-left", delay: "0s" },
  { text: "It's Ultra Max Premium Pro! 🚀", type: "chat-right", delay: "0.4s" },
  { text: "Wow, the animations are super smooth.", type: "chat-left", delay: "0.8s" }
];

messages.forEach(msg => {
  const bubble = document.createElement('div');
  bubble.className = `chat-bubble ${msg.type}`;
  bubble.innerText = msg.text;
  bubble.style.animationDelay = msg.delay;
  wrap.appendChild(bubble);
});

c.appendChild(wrap);
